//! Loader and painters for the offline-baked 2x HTML/CSS panel plate, sprite atlas, and layout.
//!
//! Assets are generated by `tools/bake_panel_from_html.py` into `crates/nord-gui/assets/baked/`.

use std::collections::BTreeMap;
use std::sync::Arc;

use egui::{
    pos2, vec2, Color32, ColorImage, Context, Painter, Rect, TextureHandle, TextureOptions, Vec2,
};
use serde::Deserialize;

/// Embedded 2x static panel plate PNG (moving caps, LEDs, and OLED content hidden).
pub const BAKED_PLATE_2X_PNG: &[u8] = include_bytes!("../assets/baked/panel_plate_2x.png");

/// Embedded 2x transparent component sprite atlas PNG.
pub const BAKED_SPRITES_2X_PNG: &[u8] = include_bytes!("../assets/baked/panel_sprites_2x.png");

/// Embedded sprite atlas manifest JSON.
pub const BAKED_SPRITES_JSON: &str = include_str!("../assets/baked/panel_sprites.json");

/// Embedded DOM-extracted normalized control layout JSON.
pub const BAKED_LAYOUT_JSON: &str = include_str!("../assets/baked/panel_layout.json");

/// Normalized `[0..1]` + logical pixel rect extracted from the HTML/CSS prototype.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedRect {
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub px: [i32; 4],
}

impl BakedRect {
    /// Map this normalized rect into an arbitrary target `container` rect on screen.
    #[must_use]
    pub fn in_rect(&self, container: Rect) -> Rect {
        let min = pos2(
            container.left() + self.x * container.width(),
            container.top() + self.y * container.height(),
        );
        let size = vec2(self.w * container.width(), self.h * container.height());
        Rect::from_min_size(min, size)
    }
}

/// Logical chassis pixel dimensions at 1x scale.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedSize {
    pub width: u32,
    pub height: u32,
}

/// Knob metadata from `panel_layout.json`.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedKnob {
    pub index: usize,
    pub encoder: bool,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub px: [i32; 4],
}

/// Pill button metadata from `panel_layout.json`.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedButton {
    pub index: usize,
    pub variant: String,
    pub vertical: bool,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub px: [i32; 4],
}

/// LED metadata from `panel_layout.json`.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedLed {
    pub index: usize,
    pub id: Option<String>,
    pub split: bool,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub px: [i32; 4],
}

/// Keybed key metadata (`midi` 21..=108) from `panel_layout.json`.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedKey {
    pub midi: u8,
    pub black: bool,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub px: [i32; 4],
}

/// Indexed layout (`panel_layout.json`) for all bays, controls, LEDs, OLEDs, and keys.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedPanelLayout {
    pub chassis_px: BakedSize,
    pub bays: BTreeMap<String, BakedRect>,
    pub knobs: Vec<BakedKnob>,
    pub buttons: Vec<BakedButton>,
    pub faders: Vec<BakedRect>,
    pub drawbars: Vec<BakedRect>,
    pub leds: Vec<BakedLed>,
    pub oleds: BTreeMap<String, BakedRect>,
    pub wheels: BTreeMap<String, BakedRect>,
    pub keys: Vec<BakedKey>,
}

/// Single packed sprite entry inside `panel_sprites_2x.png`.
#[derive(Clone, Debug, Deserialize)]
pub struct BakedSpriteEntry {
    pub px: [u32; 4],
    pub uv: [f32; 4],
    pub source: String,
}

impl BakedSpriteEntry {
    /// Normalized `[0..1]` UV rect for `egui::Painter::image`.
    #[must_use]
    pub fn uv_rect(&self) -> Rect {
        Rect::from_min_max(pos2(self.uv[0], self.uv[1]), pos2(self.uv[2], self.uv[3]))
    }

    /// Logical size in 1x UI points (`px / scale`).
    #[must_use]
    pub fn logical_size(&self, scale: u32) -> Vec2 {
        let s = scale.max(1) as f32;
        vec2(self.px[2] as f32 / s, self.px[3] as f32 / s)
    }
}

/// Sprite atlas manifest (`panel_sprites.json`).
#[derive(Clone, Debug, Deserialize)]
pub struct BakedSpritesManifest {
    pub scale: u32,
    pub atlas_px: [u32; 2],
    pub sprites: BTreeMap<String, BakedSpriteEntry>,
}

/// Single horizontal tile of the baked static plate (respects `egui`'s 2048px max texture side).
#[derive(Clone)]
pub struct BakedPlateTile {
    pub texture: TextureHandle,
    pub u_start: f32,
    pub u_end: f32,
}

/// GPU-uploaded 2x baked plate + sprite atlas + parsed manifests.
#[derive(Clone)]
pub struct BakedPanelAssets {
    pub plate_tiles: Vec<BakedPlateTile>,
    pub sprites: TextureHandle,
    pub manifest: Arc<BakedSpritesManifest>,
    pub layout: Arc<BakedPanelLayout>,
}

impl BakedPanelAssets {
    /// Decode embedded 2x PNGs and JSON manifests and upload textures once to `ctx`.
    pub fn load(ctx: &Context) -> Self {
        let max_side = ctx.input(|i| i.max_texture_side).clamp(512, 2048);
        let plate_tiles = load_plate_tiles(ctx, BAKED_PLATE_2X_PNG, max_side);
        let sprites = load_png_texture(ctx, "ns4_baked_sprites_2x", BAKED_SPRITES_2X_PNG);
        let manifest: BakedSpritesManifest =
            serde_json::from_str(BAKED_SPRITES_JSON).expect("Valid panel_sprites.json");
        let layout: BakedPanelLayout =
            serde_json::from_str(BAKED_LAYOUT_JSON).expect("Valid panel_layout.json");
        Self {
            plate_tiles,
            sprites,
            manifest: Arc::new(manifest),
            layout: Arc::new(layout),
        }
    }

    /// Return the cached `BakedPanelAssets` for `ctx`, loading and uploading it once on first call.
    pub fn get_or_load(ctx: &Context) -> Self {
        let id = egui::Id::new("ns4_baked_panel_assets_v1");
        if let Some(existing) = ctx.data(|d| d.get_temp::<Self>(id)) {
            return existing;
        }
        let loaded = Self::load(ctx);
        ctx.data_mut(|d| d.insert_temp(id, loaded.clone()));
        loaded
    }

    /// Paint the full static 2x panel plate into `rect` across its horizontal tiles.
    pub fn paint_plate(&self, painter: &Painter, rect: Rect) {
        let full_uv = Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0));
        for tile in &self.plate_tiles {
            let tile_rect = Rect::from_min_max(
                pos2(rect.left() + tile.u_start * rect.width(), rect.top()),
                pos2(rect.left() + tile.u_end * rect.width(), rect.bottom()),
            );
            painter.image(tile.texture.id(), tile_rect, full_uv, Color32::WHITE);
        }
    }

    /// Paint a named sprite from the 2x atlas into `rect` with `tint` (returns `false` if missing).
    pub fn paint_sprite(&self, painter: &Painter, name: &str, rect: Rect, tint: Color32) -> bool {
        let Some(entry) = self.manifest.sprites.get(name) else {
            return false;
        };
        painter.image(self.sprites.id(), rect, entry.uv_rect(), tint);
        true
    }
}

fn load_plate_tiles(ctx: &Context, bytes: &[u8], max_side: usize) -> Vec<BakedPlateTile> {
    let img = image::load_from_memory(bytes).expect("Embedded baked plate PNG must be valid");
    let rgba = img.to_rgba8();
    let total_w = rgba.width() as usize;
    let total_h = rgba.height() as usize;
    let mut tiles = Vec::new();
    let mut x = 0usize;
    let mut idx = 0usize;
    while x < total_w {
        let w = (total_w - x).min(max_side);
        let mut buf = Vec::with_capacity(w * total_h * 4);
        for row in 0..total_h {
            let start = (row * total_w + x) * 4;
            buf.extend_from_slice(&rgba.as_raw()[start..start + w * 4]);
        }
        let color_image = ColorImage::from_rgba_unmultiplied([w, total_h], &buf);
        let texture = ctx.load_texture(
            format!("ns4_baked_plate_2x_tile_{idx}"),
            color_image,
            TextureOptions::LINEAR,
        );
        tiles.push(BakedPlateTile {
            texture,
            u_start: x as f32 / total_w as f32,
            u_end: (x + w) as f32 / total_w as f32,
        });
        x += w;
        idx += 1;
    }
    tiles
}

fn load_png_texture(ctx: &Context, id: &str, bytes: &[u8]) -> TextureHandle {
    let img = image::load_from_memory(bytes).expect("Embedded baked PNG must be valid");
    let rgba = img.to_rgba8();
    let (w, h) = (rgba.width() as usize, rgba.height() as usize);
    let color_image = ColorImage::from_rgba_unmultiplied([w, h], &rgba.into_raw());
    ctx.load_texture(id, color_image, TextureOptions::LINEAR)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn baked_manifests_and_pngs_are_valid() {
        let plate_img = image::load_from_memory(BAKED_PLATE_2X_PNG).expect("Valid plate PNG");
        assert!(plate_img.width() > 4000);
        assert!(plate_img.height() > 1000);

        let sprites_img = image::load_from_memory(BAKED_SPRITES_2X_PNG).expect("Valid sprites PNG");
        assert!(sprites_img.width() > 100);

        let manifest: BakedSpritesManifest =
            serde_json::from_str(BAKED_SPRITES_JSON).expect("Valid sprites JSON");
        assert_eq!(manifest.scale, 2);
        assert_eq!(manifest.sprites.len(), 13);
        assert!(manifest.sprites.contains_key("knob_pot_cap"));

        let layout: BakedPanelLayout =
            serde_json::from_str(BAKED_LAYOUT_JSON).expect("Valid layout JSON");
        assert_eq!(layout.bays.len(), 6);
        assert_eq!(layout.keys.len(), 88);
        assert_eq!(layout.drawbars.len(), 9);
        assert!(layout.oleds.contains_key("main"));
        assert!(layout.oleds.contains_key("synth"));
    }

    #[test]
    fn loads_gpu_textures_and_paints_cleanly() {
        let ctx = Context::default();
        let mut loaded = None;
        let _ = ctx.run(Default::default(), |ctx| {
            let assets = BakedPanelAssets::get_or_load(ctx);
            let cached = BakedPanelAssets::get_or_load(ctx);
            assert_eq!(assets.plate_tiles.len(), cached.plate_tiles.len());
            assert_eq!(
                assets.plate_tiles[0].texture.id(),
                cached.plate_tiles[0].texture.id()
            );
            let painter = ctx.layer_painter(egui::LayerId::background());
            let plate_rect = Rect::from_min_size(pos2(0.0, 0.0), vec2(1200.0, 320.0));
            assets.paint_plate(&painter, plate_rect);
            assert!(assets.paint_sprite(
                &painter,
                "btn_black_up",
                Rect::from_min_size(pos2(10.0, 10.0), vec2(34.0, 17.0)),
                Color32::WHITE,
            ));
            assert!(!assets.paint_sprite(&painter, "nonexistent", plate_rect, Color32::WHITE,));
            loaded = Some((
                assets.layout.chassis_px.width,
                assets.manifest.sprites.len(),
            ));
        });
        let (w, n) = loaded.expect("baked assets loaded");
        assert!(w > 2000);
        assert_eq!(n, 13);
    }
}
